import { Component, input } from '@angular/core';
import { TablerIconComponent } from '@tabler/icons-angular';

export type HrmStatTone = 'primary' | 'success' | 'warning' | 'error' | 'info' | 'neutral';
export type HrmStatDelta = 'up' | 'down' | 'neutral';
/** Kiểu hiển thị: default (thẻ nền trắng, viền) · gradient (nền gradient nhiều màu, icon mờ góc)
 *  · pastel (nền tint pastel theo tone + icon disc SOLID màu đậm — token tag-hue tự flip dark). */
export type HrmStatVariant = 'default' | 'gradient' | 'pastel';
/** Chiều thẻ: compact (ngang, cao 96px) · tall (dọc, cao hơn — icon trên, số/nhãn dưới). */
export type HrmStatOrientation = 'compact' | 'tall';
/** Màu gradient (variant='gradient') — neo hue ramp token, tự bám theme. */
export type HrmStatGradient = 'blue' | 'cyan' | 'teal' | 'green' | 'purple' | 'pink' | 'amber' | 'yellow' | 'indigo';

/** hrm-stat-card — thẻ chỉ số KPI dashboard, cao cố định 96px. Hai kiểu:
 *  - default: nền trắng + viền, huy hiệu icon tô nhạt theo tone, số + nhãn + mức thay đổi.
 *  - gradient: nền gradient nhiều màu + huy hiệu icon nền trắng + chính icon đó phóng to mờ ở góc.
 *  Icon = Tabler object. Màu icon/gradient/delta theo token → tự bám Light/Dark + brand.
 *  Slot [scChart]: nhúng đồ thị mini (sparkline) bên phải (chỉ hợp variant default). */
@Component({
  selector: 'hrm-stat-card',
  imports: [TablerIconComponent],
  template: `
    @if ((variant() === 'gradient' || orientation() === 'tall') && icon()) {
      <span class="sc-bigicon" aria-hidden="true"><tabler-icon [icon]="$any(icon())" [size]="120" [stroke]="1.5" /></span>
    }
    @if (icon()) {
      <div class="sc-ic" [attr.data-tone]="tone()"><tabler-icon [icon]="$any(icon())" [size]="28" /></div>
    }
    <div class="sc-body">
      <div class="sc-top">
        <span class="sc-value">{{ value() }}</span>
        @if (delta()) { <span class="sc-delta" [attr.data-tone]="deltaTone()">{{ delta() }}</span> }
      </div>
      <div class="sc-label">{{ label() }}</div>
    </div>
    <div class="sc-chart"><ng-content select="[scChart]" /></div>
  `,
  host: {
    class: 'hrm-stat-card',
    '[attr.data-variant]': 'variant()',
    '[attr.data-gradient]': 'gradient()',
    '[attr.data-orientation]': 'orientation()',
    '[attr.data-tone]': 'tone()',
  },
  styles: [`
:host {
  position: relative; display: flex; align-items: center; gap: 14px; isolation: isolate;
  height: 96px; padding: 0 20px; overflow: hidden;
  background: var(--bg-surface); border: 1px solid var(--border-sub); border-radius: var(--radius-2xl);
}
/* Chiều tall: dọc, cao cố định 152px — icon trên, số/nhãn canh mép DƯỚI. Tỉ lệ ~3:2 gọn mắt,
   không để khoảng trống chết ở giữa. */
:host([data-orientation='tall']) {
  flex-direction: column; align-items: flex-start; justify-content: space-between;
  height: 152px; padding: 18px 20px; gap: 0;
}
:host([data-orientation='tall']) .sc-body { flex: none; }

/* variant gradient: nền gradient + chữ trắng, không viền. */
:host([data-variant='gradient']) {
  border: 0; color: var(--static-white, #fff);
  background: linear-gradient(150deg, var(--_g1, var(--purple-400)) 0%, var(--_g2, var(--purple-600)) 100%);
}
/* Vòng tròn đồng tâm mờ toả từ góc dưới-phải (hoạ tiết nền, chỉ gradient). */
:host([data-variant='gradient'])::before {
  content: ''; position: absolute; right: -60px; bottom: -72px; width: 300px; height: 300px; z-index: -1;
  border-radius: 50%; pointer-events: none;
  background: repeating-radial-gradient(circle at center, transparent 0 22px, color-mix(in srgb, var(--static-white) 7%, transparent) 22px 24px);
}
:host([data-variant='gradient'][data-gradient='blue'])   { --_g1: var(--blue-400);   --_g2: var(--blue-600);   --_ic: var(--blue-600); }
:host([data-variant='gradient'][data-gradient='cyan'])   { --_g1: var(--cyan-400);   --_g2: var(--blue-500);   --_ic: var(--cyan-600); }
:host([data-variant='gradient'][data-gradient='teal'])   { --_g1: var(--teal-400);   --_g2: var(--teal-600);   --_ic: var(--teal-600); }
:host([data-variant='gradient'][data-gradient='green'])  { --_g1: var(--green-400);  --_g2: var(--teal-600);   --_ic: var(--green-600); }
:host([data-variant='gradient'][data-gradient='purple']) { --_g1: var(--purple-400); --_g2: var(--purple-600); --_ic: var(--purple-600); }
:host([data-variant='gradient'][data-gradient='pink'])   { --_g1: var(--pink-400);   --_g2: var(--purple-600); --_ic: var(--pink-600); }
:host([data-variant='gradient'][data-gradient='amber'])  { --_g1: var(--amber-400);  --_g2: var(--amber-600);  --_ic: var(--amber-600); }
:host([data-variant='gradient'][data-gradient='yellow']) { --_g1: var(--yellow-400); --_g2: var(--amber-500);  --_ic: var(--amber-600); }
:host([data-variant='gradient'][data-gradient='indigo']) { --_g1: var(--blue-500);   --_g2: var(--purple-700); --_ic: var(--blue-700); }

/* Icon phóng to mờ góc phải (hoạ tiết) — 1 màu bán trong suốt, đồng bộ 2 kiểu:
   gradient = TRẮNG mờ; trắng-viền = ĐEN mờ (tương phản nền). */
.sc-bigicon { position: absolute; right: -10px; bottom: -14px; z-index: -1; color: color-mix(in srgb, var(--static-white) 20%, transparent); line-height: 0; }
:host([data-variant='default']) .sc-bigicon { color: color-mix(in srgb, var(--text-strong) 7%, transparent); }

/* Huy hiệu icon — nền GRADIENT theo tone + icon TRẮNG (default). */
.sc-ic {
  flex: none; width: 46px; height: 46px; border-radius: var(--radius-lg); display: grid; place-items: center;
  color: var(--static-white, #fff);
}
.sc-ic[data-tone='primary'] { background: linear-gradient(135deg, color-mix(in srgb, var(--primary-base) 62%, var(--static-white)), var(--primary-base)); }
.sc-ic[data-tone='success'] { background: linear-gradient(135deg, var(--green-400), var(--green-600)); }
.sc-ic[data-tone='warning'] { background: linear-gradient(135deg, var(--amber-400), var(--amber-600)); }
.sc-ic[data-tone='error']   { background: linear-gradient(135deg, var(--red-400), var(--red-600)); }
.sc-ic[data-tone='info']    { background: linear-gradient(135deg, var(--cyan-400), var(--blue-500)); }
.sc-ic[data-tone='neutral'] { background: linear-gradient(135deg, color-mix(in srgb, var(--text-sub) 60%, var(--static-white)), var(--text-sub)); }
/* gradient variant: huy hiệu nền trắng, icon tô màu hue (ngược lại). */
:host([data-variant='gradient']) .sc-ic { background: var(--static-white, #fff); color: var(--_ic, var(--primary-base)); box-shadow: 0 4px 12px rgba(0,0,0,.12); }

/* ── variant pastel: thẻ TRẮNG nổi shadow mềm (không viền đậm) + huy hiệu disc TINT pastel
   (cặp tag-hue TỰ FLIP dark) + icon MÀU ĐẬM bên trong — value trên, label dưới. ── */
:host([data-variant='pastel']) {
  background: var(--bg-surface); border-color: transparent;
  box-shadow: var(--shadow-regular-sm);
}
:host([data-variant='pastel'][data-tone='primary']) { --_pbg: var(--primary-bg-subtle); --_pic: var(--primary-base); }
:host([data-variant='pastel'][data-tone='success']) { --_pbg: var(--tag-green-bg);  --_pic: var(--green-500); }
:host([data-variant='pastel'][data-tone='warning']) { --_pbg: var(--tag-amber-bg);  --_pic: var(--amber-500); }
:host([data-variant='pastel'][data-tone='error'])   { --_pbg: var(--tag-red-bg);    --_pic: var(--red-500); }
:host([data-variant='pastel'][data-tone='info'])    { --_pbg: var(--tag-cyan-bg);   --_pic: var(--cyan-500); }
:host([data-variant='pastel'][data-tone='neutral']) { --_pbg: var(--bg-surface-subtle); --_pic: var(--text-sub); }
:host([data-variant='pastel']) .sc-ic {
  background: var(--_pbg, var(--bg-surface-subtle)); color: var(--_pic, var(--primary-base));
  border-radius: var(--radius-full);
}
/* pastel: label phụ nhỏ hơn (fs-13) — value là nhân vật chính, label không tranh chỗ ⇒ ít bị cắt chữ. */
:host([data-variant='pastel']) .sc-label { font-size: var(--fs-13); }

.sc-body { flex: 1; min-width: 0; }
.sc-top { display: flex; align-items: baseline; gap: 8px; flex-wrap: wrap; }
.sc-value { font-size: var(--fs-26); font-weight: 700; line-height: 1.15; color: var(--text-strong); font-variant-numeric: tabular-nums; white-space: nowrap; }
:host([data-variant='gradient']) .sc-value { color: var(--static-white, #fff); }
/* Nhãn (subtext) — to + đậm hơn chút cho dễ đọc. */
.sc-label { margin-top: 2px; font-size: var(--fs-15); font-weight: 500; color: var(--text-sub); line-height: 1.35; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
:host([data-variant='gradient']) .sc-label { color: color-mix(in srgb, var(--static-white) 92%, transparent); }
/* tall: số to hơn chút, icon huy hiệu 48px. */
:host([data-orientation='tall']) .sc-value { font-size: var(--fs-28); }
:host([data-orientation='tall']) .sc-ic { width: 48px; height: 48px; }
:host([data-orientation='tall']) .sc-bigicon { right: -12px; bottom: -16px; }
:host([data-orientation='tall']) .sc-bigicon ::ng-deep svg { width: 124px; height: 124px; }
.sc-delta { font-size: var(--fs-12); font-weight: 500; white-space: nowrap; }
.sc-delta[data-tone='up']      { color: var(--success-base); }
.sc-delta[data-tone='down']    { color: var(--error-base); }
.sc-delta[data-tone='neutral'] { color: var(--text-sub); }
:host([data-variant='gradient']) .sc-delta { color: color-mix(in srgb, var(--static-white) 90%, transparent); }

.sc-chart { flex: none; align-self: center; display: flex; align-items: center; }
.sc-chart:empty { display: none; }
  `],
})
export class HrmStatCard {
  readonly label = input('');
  readonly value = input<string | number>('');
  readonly icon = input<unknown>(null);
  readonly tone = input<HrmStatTone>('primary');
  readonly delta = input('');
  readonly deltaTone = input<HrmStatDelta>('neutral');
  /** default (nền trắng) | gradient (nền gradient + icon mờ góc). */
  readonly variant = input<HrmStatVariant>('default');
  /** compact (ngang, 96px) | tall (dọc, cao hơn — icon trên, số/nhãn dưới). */
  readonly orientation = input<HrmStatOrientation>('compact');
  /** Màu gradient khi variant='gradient'. */
  readonly gradient = input<HrmStatGradient>('purple');
}
